WITH remaining_keys AS (SELECT id FROM employees EXCEPT SELECT id FROM employees WHERE email LIKE '%@outlook.com'), reconciled AS (SELECT s.* FROM employees s INNER JOIN remaining_keys k ON s.id = k.id) SELECT CASE WHEN salary >= 160000 THEN 'LARGE' ELSE 'SMALL' END AS salary_tier, SUM(CASE WHEN job_title = 'Engineer' THEN salary ELSE 0 END) AS engineer_salary, SUM(CASE WHEN job_title = 'Engineer' THEN salary ELSE 0 END) AS engineer_salary_2, APPROX_PERCENTILE(salary, 0.5) AS salary_p50 FROM reconciled GROUP BY CASE WHEN salary >= 160000 THEN 'LARGE' ELSE 'SMALL' END ORDER BY salary_p50 DESC NULLS LAST;
